import{_ as e,o as d,c as r,a5 as o}from"./chunks/framework.0V7P45eC.js";const u=JSON.parse('{"title":"Benchmarks: fuzzy-toolkit vs Fuse.js, fuzzysort, string-similarity, fastest-levenshtein","description":"Speed and accuracy of fuzzy-toolkit against Fuse.js, fuzzysort, match-sorter, string-similarity and fastest-levenshtein, on real data: song titles, English words, world cities.","frontmatter":{"title":"Benchmarks: fuzzy-toolkit vs Fuse.js, fuzzysort, string-similarity, fastest-levenshtein","description":"Speed and accuracy of fuzzy-toolkit against Fuse.js, fuzzysort, match-sorter, string-similarity and fastest-levenshtein, on real data: song titles, English words, world cities."},"headers":[],"relativePath":"guide/benchmarks.md","filePath":"guide/benchmarks.md","lastUpdated":1795827502000}'),s={name:"guide/benchmarks.md"};function a(i,t,n,c,h,l){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="compared-with-other-libraries" tabindex="-1">Compared with other libraries <a class="header-anchor" href="#compared-with-other-libraries" aria-label="Permalink to &quot;Compared with other libraries&quot;">​</a></h1><p>Measured with <code>npm run bench:versus</code> on public data (Spotify song titles, the 20,000 most common English words, 151,000 world cities), Node 22 on a standard GitHub runner (ubuntu-latest), median of 7 runs. Every library gets the same inputs. Run it yourself, or start the Benchmarks workflow of the repository: the numbers move a little from one machine to another, the ratios much less.</p><h2 id="string-similarity" tabindex="-1">string-similarity <a class="header-anchor" href="#string-similarity" aria-label="Permalink to &quot;string-similarity&quot;">​</a></h2><p><code>fuzzy-toolkit/string-similarity</code> returns exactly the same numbers as <code>string-similarity</code> (checked on 20,000 real pairs and thousands of random ones in the tests).</p><table tabindex="0"><thead><tr><th>Task</th><th>string-similarity</th><th>fuzzy-toolkit</th><th></th></tr></thead><tbody><tr><td><code>compareTwoStrings</code>, 20,000 title pairs</td><td>35.8 ms</td><td>17.9 ms</td><td><strong>2× faster</strong></td></tr><tr><td><code>findBestMatch</code>, 1,000 queries × 2,000 titles</td><td>3.1 s</td><td>0.84 s</td><td><strong>3.7× faster</strong></td></tr></tbody></table><h2 id="did-you-mean" tabindex="-1">&quot;Did you mean…?&quot; <a class="header-anchor" href="#did-you-mean" aria-label="Permalink to &quot;&quot;Did you mean…?&quot;&quot;">​</a></h2><p>500 misspelled words against the 20,000 most common English words.</p><table tabindex="0"><thead><tr><th></th><th>Right word</th><th>Time</th></tr></thead><tbody><tr><td>string-similarity <code>findBestMatch</code></td><td>39.0 %</td><td>4.8 s</td></tr><tr><td>fuzzy-toolkit <code>createIndex(words).closest()</code></td><td><strong>93.4 %</strong></td><td><strong>0.22 s</strong> (22× faster)</td></tr></tbody></table><h2 id="search-as-you-type" tabindex="-1">Search as you type <a class="header-anchor" href="#search-as-you-type" aria-label="Permalink to &quot;Search as you type&quot;">​</a></h2><p>300 typed queries (the start of a title, with a typo) over 23,450 song titles, top 10.</p><table tabindex="0"><thead><tr><th></th><th>Wanted title found</th><th>Time per query</th></tr></thead><tbody><tr><td>Fuse.js</td><td>65.3 %</td><td>60.6 ms</td></tr><tr><td>fuzzysort</td><td>21.7 %</td><td>0.6 ms</td></tr><tr><td>fuzzy-toolkit <code>createIndex(titles, { preset: &#39;search&#39; })</code></td><td><strong>82.7 %</strong></td><td><strong>4.4 ms</strong></td></tr><tr><td>fuzzy-toolkit/fuse, the same code as Fuse.js</td><td>80.3 %</td><td>4.0 ms</td></tr></tbody></table><p>fuzzysort is the fastest but only matches letters in order, so a typo loses the result. fuzzy-toolkit finds more than Fuse.js, 13 times faster.</p><h2 id="acronyms" tabindex="-1">Acronyms <a class="header-anchor" href="#acronyms" aria-label="Permalink to &quot;Acronyms&quot;">​</a></h2><p>150 city names of 3 words or more typed as their initials (<code>nyc</code>), among 151,186 cities, top 10.</p><table tabindex="0"><thead><tr><th></th><th>Found</th><th>Time per query</th></tr></thead><tbody><tr><td>match-sorter</td><td>59.3 %</td><td>85.1 ms</td></tr><tr><td>fuzzy-toolkit <code>createIndex(cities, { preset: &#39;search&#39; })</code></td><td><strong>82.0 %</strong></td><td><strong>11.8 ms</strong></td></tr></tbody></table><h2 id="levenshtein-distance" tabindex="-1">Levenshtein distance <a class="header-anchor" href="#levenshtein-distance" aria-label="Permalink to &quot;Levenshtein distance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pairs</th><th>fastest-levenshtein</th><th>fuzzy-toolkit <code>levenshtein</code></th></tr></thead><tbody><tr><td>20,000 titles + 20,000 words</td><td>11.0 ms</td><td><strong>5.4 ms</strong> (2×)</td></tr><tr><td>2,000 sentences of 100-400 characters, with typos</td><td>19.1 ms</td><td><strong>4.9 ms</strong> (3.9×)</td></tr></tbody></table><p><code>damerau</code> (swapped letters count once) costs about the same: 5.6 ms on the sentences.</p><h2 id="dedupe" tabindex="-1">Dedupe <a class="header-anchor" href="#dedupe" aria-label="Permalink to &quot;Dedupe&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Time</th></tr></thead><tbody><tr><td><code>dedupe()</code>, 5,000 song titles, typos included</td><td>0.85 s</td></tr><tr><td><code>dedupe(..., { method: &#39;fingerprint&#39; })</code>, 20,000 titles</td><td>61 ms</td></tr></tbody></table><h2 id="saved-index" tabindex="-1">Saved index <a class="header-anchor" href="#saved-index" aria-label="Permalink to &quot;Saved index&quot;">​</a></h2><p>151,186 cities: <code>createIndex</code> takes 175 ms, <code>loadIndex</code> from JSON 86 ms. Fuse.js builds its (lighter) index in 23 ms, but searches it 7 to 14 times slower.</p><h2 id="size" tabindex="-1">Size <a class="header-anchor" href="#size" aria-label="Permalink to &quot;Size&quot;">​</a></h2><p>Minified and gzipped, with <code>npm run size</code>:</p><table tabindex="0"><thead><tr><th>Import</th><th>Size</th></tr></thead><tbody><tr><td><code>levenshtein</code>, <code>damerau</code></td><td>1.3 kB</td></tr><tr><td><code>fuzzy-toolkit/string-similarity</code></td><td>0.8 kB</td></tr><tr><td><code>similarity</code>, <code>isMatch</code></td><td>10.0 kB</td></tr><tr><td><code>check</code>, <code>checkAll</code></td><td>10.6 kB</td></tr><tr><td><code>mapFields</code></td><td>10.8 kB</td></tr><tr><td><code>findAll</code></td><td>11.5 kB</td></tr><tr><td><code>createIndex</code>, <code>search</code>, <code>highlight</code></td><td>13.2 kB</td></tr><tr><td><code>fuzzy-toolkit/react</code>, <code>/vue</code>, <code>/svelte</code></td><td>13.5 kB</td></tr><tr><td><code>repair</code></td><td>14.6 kB</td></tr><tr><td><code>createMatcher</code> (every method)</td><td>14.8 kB</td></tr><tr><td><code>fuzzy-toolkit/fuse</code></td><td>15.5 kB</td></tr><tr><td>everything</td><td>20.3 kB</td></tr><tr><td>one extra language (<code>lang/es</code>)</td><td>+0.6 kB</td></tr></tbody></table><p>The package is marked <code>&quot;sideEffects&quot;: false</code>, so bundlers keep only what you import. A matcher from <code>createMatcher</code> is one object with every method, so it always carries all of them: import the functions you call when size matters.</p>',26)])])}const y=e(s,[["render",a]]);export{u as __pageData,y as default};
